<template><Teleport to="body"><div class="toast-stack" role="status" aria-live="polite"><div v-for="toast in toasts.items" :key="toast.id" :class="['toast',toast.type,{actionable:toast.action}]" :role="toast.action?'button':undefined" :tabindex="toast.action?0:undefined" @click="activate(toast)" @keydown.enter="activate(toast)"><span><strong v-if="toast.title">{{ toast.title }}</strong>{{ toast.message }}</span><button @click.stop="dismiss(toast.id)" aria-label="بستن">×</button></div></div></Teleport></template>
<script setup>import { useCostToast } from '@/composables/useCostToast'; const { toasts, dismiss, activate } = useCostToast()</script>
<style scoped>.toast-stack{position:fixed;top:max(1rem,env(safe-area-inset-top));left:max(1rem,env(safe-area-inset-left));z-index:1400;display:grid;gap:.6rem;width:min(390px,calc(100vw - 2rem))}.toast{display:flex;align-items:center;justify-content:space-between;gap:.75rem;padding:.85rem 1rem;border-radius:10px;box-shadow:0 12px 28px #1113;font-size:.9rem}.toast span{display:grid;gap:.25rem}.toast strong{font-size:1rem}.toast.success{background:#166534;color:#fff}.toast.error{background:#b91c1c;color:#fff}.toast.order{background:#075985;color:#fff;border-right:4px solid #7dd3fc}.toast.actionable{cursor:pointer}.toast button{border:0;background:transparent;color:inherit;font-size:1.25rem;cursor:pointer}</style>
